import {createNativeStackNavigator} from '@react-navigation/native-stack';
import {PaperProvider} from 'react-native-paper';
import {LIST_SCREEN} from './helper';
import Toast from 'react-native-toast-message';
import toastConfig from '../utils/ToastConfig';
import {ApplicationProvider, IconRegistry} from '@ui-kitten/components';
import {EvaIconsPack} from '@ui-kitten/eva-icons';
import * as eva from '@eva-design/eva';
import {default as theme} from '../../custom-theme.json'; // <-- Import app theme
import {default as mapping} from '../../mapping.json'; // <-- Import app mapping
import {useUserService} from '../hooks/apiHooks/useAPI';
import {useUserStore} from '../zutand/user-store';
import {useEffect} from 'react';
import {useAppSelector} from '../hooks/useRedux';

const Stack = createNativeStackNavigator();

const ETaskNavigation = () => {
  const userServices = useUserService();
  const {setListOrgIn} = useUserStore();

  const {dataAccount} = useAppSelector(state => state.account);

  useEffect(() => {
    getListAllOrgIn();
  }, []);
  const getListAllOrgIn = async () => {
    const params = {
      orgIn: `/${dataAccount.orgIn?.split('/')?.[1] || 7}`,
    };
    const data = await userServices.findListOrgIn(params);
    if (data) {
      setListOrgIn(data);
    }
  };
  return (
    <>
      <IconRegistry icons={[EvaIconsPack]} />
      <ApplicationProvider
        customMapping={mapping as any}
        {...eva}
        theme={{...eva.light, ...theme}}>
        <PaperProvider>
          <Stack.Navigator screenOptions={{headerShown: false}}>
            {LIST_SCREEN.map(screen => (
              <Stack.Screen
                key={screen.name}
                name={screen.name}
                component={screen.component}
              />
            ))}
          </Stack.Navigator>
          <Toast config={toastConfig} />
        </PaperProvider>
      </ApplicationProvider>
    </>
  );
};

export default ETaskNavigation;
